import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  Pcg32, pcgHash32, quinticFade, sinPoly, cosPoly, f32,
} from '../src/math/determinism.js';

test('determinism: PCG matches the published RXS-M-XS reference vectors', () => {
  // Independent exact vectors from the published formulas
  // (PCG paper section 6.3.4; Jarzynski/Olano hash form), generated by an
  // exact integer-arithmetic Python implementation, not by this code.
  const g0 = new Pcg32(0);
  assert.deepEqual(
    [g0.next(), g0.next(), g0.next(), g0.next(), g0.next(), g0.next()],
    [0x07bb2fe2, 0x22b6b6bc, 0x3bf6e0b1, 0x572f7439, 0x86fc4ddc, 0x34659162],
  );
  const g42 = new Pcg32(42);
  assert.deepEqual(
    [g42.next(), g42.next(), g42.next()],
    [0x48f432ff, 0x465e7708, 0xa1decb48],
  );
  const gmax = new Pcg32(0xffffffff);
  assert.deepEqual(
    [gmax.next(), gmax.next()],
    [0xe62a4902, 0x498239f9],
  );
  // One-shot hash agrees with the stream.
  assert.equal(pcgHash32(0), 0x07bb2fe2);
  assert.equal(pcgHash32(1), 0xa8beea3c);
  assert.equal(pcgHash32(12345), 0xf45ead0e);
  // Deterministic across instances.
  const a = new Pcg32(7), b = new Pcg32(7);
  assert.equal(a.next(), b.next());
});

test('determinism: pcg unit() stays in [0,1) and is exact at the multiply', () => {
  const g = new Pcg32(123);
  for (let i = 0; i < 1000; i++) {
    const u = g.unit();
    assert.ok(u >= 0 && u < 1);
  }
  // (h >> 8) < 2^24 times 2^-24 is dyadic: exact in float64 and float32.
  const h = 0xffffff;
  assert.equal((h >>> 8) * 2 ** -24, f32((h >>> 8) * 2 ** -24));
});

test('determinism: quintic fade matches 6t^5 - 15t^4 + 10t^3', () => {
  for (const t of [0, 0.25, 0.5, 0.75, 1]) {
    const ref = 6 * t ** 5 - 15 * t ** 4 + 10 * t ** 3;
    assert.ok(Math.abs(quinticFade(t) - ref) < 1e-15);
  }
  assert.equal(quinticFade(0), 0);
  assert.equal(quinticFade(1), 1);
  assert.equal(quinticFade(0.5), 0.5);
});

test('determinism: sinPoly within 1e-9 of Math.sin everywhere', () => {
  let worst = 0;
  for (let i = 0; i <= 2000; i++) {
    const x = -10 + (20 * i) / 2000;
    worst = Math.max(worst, Math.abs(sinPoly(x) - Math.sin(x)));
  }
  assert.ok(worst <= 1e-9, `worst error ${worst}`);
  // cos via the same path.
  let worstC = 0;
  for (let i = 0; i <= 500; i++) {
    const x = -5 + (10 * i) / 500;
    worstC = Math.max(worstC, Math.abs(cosPoly(x) - Math.cos(x)));
  }
  assert.ok(worstC <= 1e-9, `worst cos error ${worstC}`);
});

test('determinism: f32 is the canonical float32 narrowing', () => {
  assert.equal(f32(0.1), Math.fround(0.1));
  assert.equal(f32(f32(1.5) * f32(2.25)), Math.fround(Math.fround(1.5) * Math.fround(2.25)));
});
